BEGIN TRANSACTION;
CREATE TABLE dim_period (
	period VARCHAR NOT NULL, 
	fiscal_year INTEGER NOT NULL, 
	fiscal_quarter INTEGER NOT NULL, 
	period_end_date DATE NOT NULL, 
	estimated_publish_date DATE NOT NULL, 
	PRIMARY KEY (period)
);
CREATE TABLE dim_sector (
	icb_code VARCHAR NOT NULL, 
	icb_name VARCHAR NOT NULL, 
	icb_level INTEGER NOT NULL, 
	PRIMARY KEY (icb_code)
);
CREATE TABLE dim_statement_item (
	item_id VARCHAR NOT NULL, 
	item_vi VARCHAR, 
	item_en VARCHAR, 
	statement_type VARCHAR NOT NULL, 
	PRIMARY KEY (item_id)
);
CREATE TABLE dim_symbol (
	symbol VARCHAR NOT NULL, 
	organ_name VARCHAR, 
	com_type_code VARCHAR NOT NULL, 
	icb_code VARCHAR, issue_share FLOAT, dividend_per_share_tsr FLOAT, 
	PRIMARY KEY (symbol), 
	FOREIGN KEY(icb_code) REFERENCES dim_sector (icb_code)
);
CREATE TABLE fact_price (
	symbol VARCHAR NOT NULL, 
	trade_date DATE NOT NULL, 
	open FLOAT NOT NULL, 
	high FLOAT NOT NULL, 
	low FLOAT NOT NULL, 
	close FLOAT NOT NULL, 
	volume FLOAT NOT NULL, 
	fetched_on VARCHAR NOT NULL, 
	PRIMARY KEY (symbol, trade_date), 
	FOREIGN KEY(symbol) REFERENCES dim_symbol (symbol)
);
CREATE TABLE fact_statement_line (
	symbol VARCHAR NOT NULL, 
	period VARCHAR NOT NULL, 
	item_id VARCHAR NOT NULL, 
	value FLOAT, 
	fetched_on VARCHAR NOT NULL, 
	PRIMARY KEY (symbol, period, item_id), 
	FOREIGN KEY(symbol) REFERENCES dim_symbol (symbol), 
	FOREIGN KEY(period) REFERENCES dim_period (period), 
	FOREIGN KEY(item_id) REFERENCES dim_statement_item (item_id)
);
COMMIT;
